  "count-paths-dag-mod": [{"code":"n, m = 100000, 200000\norder = [1] + r.shuffle(list(range(2, 100000))) + [100000]\nseen = set()\ne = []\nfor i in range(1, 100000):\n    e.append((order[r.int(0, i - 1)], order[i]))\n    seen.add(e[-1])\nwhile len(e) < 200000:\n    i, j = r.int(0, 100000 - 1), r.int(0, 100000 - 1)\n    if i < j and (order[i], order[j]) not in seen:\n        seen.add((order[i], order[j]))\n        e.append((order[i], order[j]))\ne = r.shuffle(e)\nreturn line([n, len(e)]) + \"\\n\" + \"\\n\".join(line(e) for e in e)","seed":1,"sha":"4ec9599fc203d176a301536c2e091a19bc852759b255bd6818810a42c5fed14a"},{"code":"k = 1000\nw = 100\nn = k * w\nnode = lambda i, j: i * w + j + 1\ne = []\nfor i in range(k - 1):\n    for j in range(w):\n        e.append((node(i, j), node(i + 1, j)))\n        e.append((node(i, j), node(i + 1, (j + 1) % w)))\nreturn line([n, len(e)]) + \"\\n\" + \"\\n\".join(line(e) for e in e)","seed":2,"sha":"984802b3942d36d5e48eeba25c4ab56f60c13e4d73f495485eb7bf755f8de590"}],
