  "fenwick-kth-element": [{"code":"qn = 200000\nops = []\nbag = []\nfor _ in range(qn):\n    k = r.int(0, 3)\n    if bag and k == 0:\n        i = r.int(0, len(bag) - 1)\n        bag[i], bag[-1] = bag[-1], bag[i]\n        ops.append(line([2, bag.pop()]))\n    elif bag and k == 1:\n        ops.append(line([3, r.int(1, len(bag))]))\n    else:\n        x = r.int(1, 10**6)\n        bag.append(x)\n        ops.append(line([1, x]))\nreturn str(qn) + \"\\n\" + \"\\n\".join(ops)","seed":1,"sha":"5fb1cbdb6f0ccb32415d67ab0afd767bb376f566dac39ad3ad3d9ca7a27c1556"}],
