  "graph-bfs-bipartite-sides": [{"code":"n, m = 100000, 200000\nside = [r.int(0, 1) for _ in range(n + 1)]\nL = [v for v in range(1, n + 1) if side[v] == 0]\nRr = [v for v in range(1, n + 1) if side[v] == 1]\nseen = set()\ne = []\nwhile len(e) < m:\n    a, b = r.choice(L), r.choice(Rr)\n    if (a, b) not in seen:\n        seen.add((a, b))\n        e.append((a, b) if r.int(0, 1) else (b, a))\nreturn line([n, len(e)]) + \"\\n\" + \"\\n\".join(line(e) for e in e)","seed":1,"sha":"19d86e3c7d19c82889234c58d3d5938bd1eb3ec5cd62a718a0579166bc8dac43"},{"code":"n = 100000\ne = tree_edges(r, n, \"path\")\nreturn line([n, len(e)]) + \"\\n\" + \"\\n\".join(line(e) for e in e)","seed":2,"sha":"f4d1518033af5230dee5e27631bcbd985074ae1552e2f646b03dfe32ef12fcef"}],
