  "tree-path-sum-exists": [{"code":"n = 100000\nreturn line([n, r.int(-10**9, 10**18)]) + \"\\n\" + line(r.ints(n, -10**9, 10**9)) + \"\\n\" + \"\\n\".join(line(e) for e in tree_edges(r, n))","seed":1,"sha":"23794d91c53ae875c8e247d72561e35d9d06ee07c70c9e0dbcc977a6d161504a"},{"code":"n = 100000\nval = r.ints(n, -10**9, 10**9)\ne = tree_edges(r, n)\nadj = [[] for _ in range(n + 1)]\nfor a, b in e:\n    adj[a].append(b)\n    adj[b].append(a)\ndist = [None] * (n + 1)\ndist[1] = val[0]\nst = [1]\nleaves = []\nwhile st:\n    v = st.pop()\n    kids = 0\n    for u in adj[v]:\n        if dist[u] is None:\n            dist[u] = dist[v] + val[u - 1]\n            st.append(u)\n            kids += 1\n    if kids == 0 and v != 1:\n        leaves.append(v)\nok = [v for v in leaves if dist[v] >= -10**9] or [None]\nS = dist[r.choice(ok)] if ok[0] else 0\nreturn line([n, S]) + \"\\n\" + line(val) + \"\\n\" + \"\\n\".join(line(e) for e in e)","seed":2,"sha":"f9171164593756e56fb197327b529a4955590566560dbe62d586bff41be9d297"}],
